import { assert, it } from "@effect/vitest";
import { RunId, ThreadId, TurnItemId } from "@t3tools/contracts";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as SqlClient from "effect/sql/SqlClient";

import * as SqlitePersistence from "../persistence/Sqlite.ts";
import * as TurnItemPositionStore from "./TurnItemPositionStore.ts";

const layerTest = TurnItemPositionStore.layer.pipe(
  Layer.provideMerge(SqlitePersistence.layerMemory),
);

it.effect("reuses positions without redundant inserts and binds late run ownership", () =>
  Effect.gen(function* () {
    const sql = yield* SqlClient.SqlClient;
    const positions = yield* TurnItemPositionStore.TurnItemPositionStoreV2;
    const input = {
      threadId: ThreadId.make("thread:position-reuse"),
      turnItemId: TurnItemId.make("item:streaming"),
      runId: null,
    };
    const first = yield* positions.allocate(input);
    assert.equal(first, 1);

    // BEFORE INSERT runs even when ON CONFLICT would discard the allocation.
    yield* sql`
      CREATE TEMP TRIGGER reject_redundant_position_insert
      BEFORE INSERT ON orchestration_v2_turn_item_positions
      WHEN EXISTS (
        SELECT 1 FROM orchestration_v2_turn_item_positions
        WHERE thread_id = NEW.thread_id AND turn_item_id = NEW.turn_item_id
      )
      BEGIN
        SELECT RAISE(ABORT, 'Existing item positions must be reused');
      END
    `;

    const next = yield* positions.allocate({
      ...input,
      turnItemId: TurnItemId.make("item:next"),
    });
    assert.equal(next, first + 1);
    assert.equal(yield* positions.allocate(input), first);
    assert.equal(
      yield* positions.allocate({
        ...input,
        turnItemId: TurnItemId.make("item:next"),
        runId: RunId.make("run:not-yet-known"),
      }),
      next,
    );
    const associated = {
      ...input,
      runId: RunId.make("run:moved"),
      runOrdinal: 2,
    };
    const moved = yield* positions.allocate(associated);
    assert.equal(moved, 2_000_001);
    assert.equal(yield* positions.allocate(associated), moved);
    assert.equal(
      yield* positions.allocate({
        ...associated,
        turnItemId: TurnItemId.make("item:next"),
      }),
      moved + 1,
    );
    assert.equal(yield* positions.allocate(input), moved);
    assert.equal(yield* positions.allocate({ ...associated, runOrdinal: 3 }), moved);
    assert.equal(
      yield* positions.allocate({ ...input, threadId: ThreadId.make("thread:other") }),
      1,
    );
  }).pipe(Effect.provide(layerTest)),
);

import { OrchestrationV2TurnItem, RunId, ThreadId, TurnItemId } from "@t3tools/contracts";
import * as Context from "effect/Context";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Schema from "effect/Schema";
import * as SqlClient from "effect/sql/SqlClient";

export class TurnItemPositionStoreError extends Schema.TaggedError<TurnItemPositionStoreError>()(
  "TurnItemPositionStoreError",
  {
    threadId: ThreadId,
    turnItemId: TurnItemId,
    cause: Schema.optional(Schema.Defect()),
  },
) {}

const isTurnItemPositionStoreError = Schema.is(TurnItemPositionStoreError);

export interface TurnItemPositionStoreV2Shape {
  readonly allocate: (input: {
    readonly threadId: ThreadId;
    readonly turnItemId: TurnItemId;
    readonly runId: RunId | null;
    readonly runOrdinal?: number;
  }) => Effect.Effect<number, TurnItemPositionStoreError>;
  readonly normalize: (
    item: OrchestrationV2TurnItem,
    runOrdinal?: number,
  ) => Effect.Effect<OrchestrationV2TurnItem, TurnItemPositionStoreError>;
}

export class TurnItemPositionStoreV2 extends Context.Service<
  TurnItemPositionStoreV2,
  TurnItemPositionStoreV2Shape
>()("t3/orchestration-v2/TurnItemPositionStore/TurnItemPositionStoreV2") {}

export const layer: Layer.Layer<TurnItemPositionStoreV2, never, SqlClient.SqlClient> = Layer.effect(
  TurnItemPositionStoreV2,
  Effect.gen(function* () {
    const sql = yield* SqlClient.SqlClient;

    const allocate: TurnItemPositionStoreV2Shape["allocate"] =
      /* This helper runs for individual orchestration events; the enclosing operation owns the span. */
      Effect.fnUntraced(
        function* ({ threadId, turnItemId, runId, runOrdinal: suppliedRunOrdinal }) {
          const existing = yield* sql<{ readonly ordinal: number }>`
          SELECT ordinal
          FROM orchestration_v2_turn_item_positions
          WHERE thread_id = ${threadId} AND turn_item_id = ${turnItemId}
          LIMIT 1
        `;
          if (existing[0] !== undefined && (existing[0].ordinal >= 1_000_000 || runId === null))
            return existing[0].ordinal;

          const runRows =
            runId === null
              ? []
              : yield* sql<{ readonly ordinal: number }>`
                SELECT ordinal
                FROM orchestration_v2_projection_runs
                WHERE thread_id = ${threadId} AND run_id = ${runId}
                LIMIT 1
              `;
          const runOrdinal = suppliedRunOrdinal ?? runRows[0]?.ordinal ?? null;
          const lowerBound = runOrdinal === null ? 0 : runOrdinal * 1_000_000;
          const upperBound = runOrdinal === null ? 999_999 : lowerBound + 999_999;
          if (existing[0] !== undefined) {
            if (runOrdinal === null) return existing[0].ordinal;
            // Late ownership evidence moves an unassociated item into its run's range.
            yield* sql`
              UPDATE orchestration_v2_turn_item_positions
              SET ordinal = (
                SELECT COALESCE(MAX(ordinal), ${lowerBound}) + 1
                FROM orchestration_v2_turn_item_positions
                WHERE thread_id = ${threadId}
                  AND ordinal >= ${lowerBound}
                  AND ordinal <= ${upperBound}
              )
              WHERE thread_id = ${threadId} AND turn_item_id = ${turnItemId}
                AND ordinal < 1000000
            `;
          } else
            yield* sql`
          INSERT INTO orchestration_v2_turn_item_positions (thread_id, turn_item_id, ordinal)
          SELECT
            ${threadId},
            ${turnItemId},
            COALESCE(MAX(ordinal), ${lowerBound}) + 1
          FROM orchestration_v2_turn_item_positions
          WHERE thread_id = ${threadId}
            AND ordinal >= ${lowerBound}
            AND ordinal <= ${upperBound}
          ON CONFLICT(thread_id, turn_item_id) DO NOTHING
        `;
          const rows = yield* sql<{ readonly ordinal: number }>`
          SELECT ordinal
          FROM orchestration_v2_turn_item_positions
          WHERE thread_id = ${threadId} AND turn_item_id = ${turnItemId}
          LIMIT 1
        `;
          const ordinal = rows[0]?.ordinal;
          if (ordinal === undefined) {
            return yield* new TurnItemPositionStoreError({
              threadId,
              turnItemId,
              cause: "Position allocation returned no row.",
            });
          }
          return ordinal;
        },
        (effect, { threadId, turnItemId }) =>
          effect.pipe(
            Effect.mapError((cause) =>
              isTurnItemPositionStoreError(cause)
                ? cause
                : new TurnItemPositionStoreError({ threadId, turnItemId, cause }),
            ),
          ),
      );

    return TurnItemPositionStoreV2.of({
      allocate,
      // Per-event normalization shares the enclosing orchestration span.
      normalize: Effect.fnUntraced(function* (item, runOrdinal) {
        return yield* allocate({
          threadId: item.threadId,
          turnItemId: item.id,
          runId: item.runId,
          ...(runOrdinal === undefined ? {} : { runOrdinal }),
        }).pipe(Effect.map((ordinal) => (item.ordinal === ordinal ? item : { ...item, ordinal })));
      }),
    });
  }),
);

import { describe, expect, it } from "vite-plus/test";
import type { SelectProviderOptionDescriptor } from "@t3tools/contracts";
import { getPromptControlledTraits, getTraitSelectChange } from "./modelTraits.ts";

describe("Fusion effort changes", () => {
  it("dispatches advertised IDs and explicit reset without changing the prompt", () => {
    const descriptor: SelectProviderOptionDescriptor = {
      id: "autoTier",
      label: "Fusion effort",
      type: "select",
      options: [
        { id: "opaque-high", label: "High" },
        { id: "disabled", label: "Max", disabledReason: "Account policy" },
        { id: "reset", label: "Provider default", isReset: true },
      ],
      currentValue: "opaque-high",
    };
    const selected = {
      ...getPromptControlledTraits([descriptor], "A bounded demo"),
      descriptors: [descriptor],
    };
    expect(getTraitSelectChange(selected, descriptor, "A bounded demo", "reset")).toEqual({
      prompt: "A bounded demo",
      modelOptions: [{ id: "autoTier", value: false }],
    });
    expect(getTraitSelectChange(selected, descriptor, "A bounded demo", "opaque-high")).toEqual({
      prompt: "A bounded demo",
      modelOptions: [{ id: "autoTier", value: "opaque-high" }],
    });
    expect(getTraitSelectChange(selected, descriptor, "A bounded demo", "disabled")).toBeNull();
    expect(getTraitSelectChange(selected, descriptor, "A bounded demo", "high")).toBeNull();
  });
});

import type { OrchestrationV2ModelExecution } from "@t3tools/contracts";
import { describe, expect, it } from "vite-plus/test";
import { modelExecutionDetail, modelExecutionSummary } from "./modelExecution.ts";

const phase: OrchestrationV2ModelExecution = {
  version: 1,
  kind: "phase",
  nativeSessionId: "session-1",
  eventId: "event-1",
  sourceTimestamp: "2026-11-02T10:00:05.000Z",
  receivedAt: "2026-11-02T10:00:08.000Z",
  status: "completed",
  model: "actual-model",
  startSource: "observed",
  startedAt: "2026-11-02T10:00:00.000Z",
  endedAt: "2026-11-02T10:00:05.000Z",
  durationMs: 4800,
  gaps: [],
};

describe("model execution presentation", () => {
  it("shows an explicit provider-default reset separately from unknown preference", () => {
    const reset: OrchestrationV2ModelExecution = {
      ...phase,
      kind: "selection",
      requestedModel: "auto",
      requestedProviderDefault: true,
      status: "effective",
    };
    expect(modelExecutionSummary(reset)).toContain("effective provider default");
    expect(modelExecutionDetail(reset)).toContain("Requested routing: provider default");
    expect(modelExecutionDetail(reset)).toContain("Effective routing: provider default");
    const pending = {
      ...reset,
      status: "pending",
      effectivePreference: "previous-tier",
      pendingPreference: null,
    };
    expect(modelExecutionDetail(pending)).toContain("Effective routing: previous-tier");
    expect(modelExecutionDetail(pending)).toContain("Pending routing: none");
  });
  it("uses provider duration rather than receipt latency and distinguishes timing evidence", () => {
    expect(modelExecutionSummary(phase)).toContain("actual-model · completed · 4.8s");
    const detail = modelExecutionDetail(phase);
    expect(detail).toContain("Provider elapsed: 4.8s");
    expect(detail).toContain(`Started (observed): ${phase.startedAt}`);
    expect(detail).toContain(`Provider event time: ${phase.sourceTimestamp}`);
    expect(detail).toContain(`Received: ${phase.receivedAt}`);
    expect(modelExecutionDetail({ ...phase, startSource: "estimated" })).toContain(
      `Started (estimated): ${phase.startedAt}`,
    );
    const { durationMs: _duration, ...withoutDuration } = phase;
    expect(modelExecutionSummary(withoutDuration)).not.toContain("5.0s");
    expect(modelExecutionDetail(withoutDuration)).toContain("Provider elapsed: not reported");
    expect(
      modelExecutionDetail({ ...phase, startSource: "unknown", startedAt: undefined }),
    ).toContain("Start: unknown");
  });

  it("keeps requested routing separate from effective, pending, and actual execution", () => {
    const route = {
      ...phase,
      kind: "route" as const,
      requestedModel: "Fusion",
      requestedPreference: "premium",
      effectivePreference: "standard",
      pendingPreference: "premium",
      activatingPreference: null,
    };
    expect(modelExecutionSummary(route)).not.toContain("actual-model");
    const detail = modelExecutionDetail(route);
    expect(detail).toContain("Routing state (not proof of model execution)");
    expect(detail).toContain("Requested model: Fusion");
    expect(detail).toContain("Requested routing: premium");
    expect(detail).toContain("Effective routing: standard");
    expect(detail).toContain("Pending routing: premium");
    expect(detail).toContain("Activating routing: none");
    expect(modelExecutionDetail({ ...route, pendingPreference: undefined })).not.toContain(
      "Pending routing:",
    );
  });

  it("surfaces fallback, failure, final provenance and incomplete telemetry without inventing success", () => {
    const failed = {
      ...phase,
      status: "failed",
      fallbackModel: "fallback-model",
      finalSourceModel: "final-model",
      finalSourcePhaseId: "final-phase",
      reason: "Provider unavailable",
      awaitingBackgroundWork: true,
      gaps: ["missing phase start", "duration incomplete"],
    };
    expect(modelExecutionSummary(failed)).toContain("failed");
    expect(modelExecutionSummary(failed)).toContain("final final-model");
    expect(modelExecutionSummary(failed)).toContain("telemetry gaps");
    const detail = modelExecutionDetail(failed);
    expect(detail).toContain("Planned fallback model (not execution evidence): fallback-model");
    expect(detail).toContain("Final source model: final-model");
    expect(detail).toContain("Final source phase: final-phase");
    expect(detail).toContain("Reason: Provider unavailable");
    expect(detail).toContain("Background work: awaiting completion");
    expect(detail).toContain("Telemetry gaps:\n- missing phase start\n- duration incomplete");
  });

  it("shows Fusion patterns and final models without reporting planned fallback as executed", () => {
    for (const pattern of ["single", "cascade", "critique"]) {
      const route: OrchestrationV2ModelExecution = {
        ...phase,
        kind: "route",
        pattern,
        syntheticModel: "opaque-fusion",
        finalSourceModel: "actual-final-model",
        fallbackModel: "unused-fallback",
      };
      expect(modelExecutionSummary(route)).toContain(`opaque-fusion · ${pattern}`);
      expect(modelExecutionSummary(route)).toContain("final actual-final-model");
      expect(modelExecutionSummary(route)).toContain("planned fallback unused-fallback");
    }
  });

  it("shows ordinary Auto resolution as selection rather than Fusion or final execution", () => {
    const resolved: OrchestrationV2ModelExecution = {
      ...phase,
      kind: "route",
      requestedModel: "auto",
      status: "resolved",
    };
    expect(modelExecutionSummary(resolved)).toContain("selected actual-model");
    expect(modelExecutionSummary(resolved)).not.toContain("final ");
    expect(modelExecutionDetail(resolved)).toContain(
      "Selected model (not execution evidence): actual-model",
    );
    expect(modelExecutionDetail(resolved)).not.toContain("Pattern:");
  });
});

import type { OrchestrationV2ModelExecution } from "@t3tools/contracts";
import { formatDuration } from "@t3tools/shared/orchestrationTiming";

export function modelExecutionSummary(execution: OrchestrationV2ModelExecution): string {
  const subject =
    execution.kind === "phase"
      ? ["Model phase", execution.model ?? "model unknown", execution.role]
      : execution.kind === "gap"
        ? ["Model telemetry gap", execution.model]
        : [
            execution.kind === "selection" ? "Model selection (requested)" : "Model routing",
            execution.syntheticModel ?? execution.requestedModel,
            execution.pattern,
            execution.status === "resolved" && execution.model
              ? `selected ${execution.model}`
              : execution.requestedProviderDefault
                ? `${execution.status === "effective" ? "effective" : "requested"} provider default`
                : undefined,
            execution.effectivePreference
              ? `effective ${execution.effectivePreference}`
              : execution.requestedPreference
                ? `requested ${execution.requestedPreference}`
                : undefined,
          ];
  return [
    ...subject,
    execution.status,
    execution.kind === "phase" && execution.durationMs !== undefined
      ? formatDuration(execution.durationMs)
      : undefined,
    execution.finalSourceModel ? `final ${execution.finalSourceModel}` : undefined,
    execution.fallbackModel ? `planned fallback ${execution.fallbackModel}` : undefined,
    execution.gaps.length > 0 ? "telemetry gaps" : undefined,
  ]
    .filter(Boolean)
    .join(" · ");
}

export function modelExecutionDetail(
  execution: OrchestrationV2ModelExecution,
  message?: string,
): string {
  const lines: string[] = message?.trim() ? [message.trim(), ""] : [];
  const add = (label: string, value: string | number | null | undefined) => {
    if (value !== undefined) lines.push(`${label}: ${value === null ? "none" : value}`);
  };
  lines.push(
    execution.kind === "selection" || execution.kind === "route"
      ? "Routing state (not proof of model execution)"
      : execution.kind === "gap"
        ? "Incomplete model execution telemetry"
        : "Provider-reported model phase",
  );
  add("Status", execution.status);
  add(
    execution.kind === "route" ? "Selected model (not execution evidence)" : "Model",
    execution.model,
  );
  add("Role", execution.role);
  add("Phase kind", execution.phaseKind);
  add("Conversation scope", execution.conversationScope);
  add("Pattern", execution.pattern);
  if (execution.plannedModels?.length)
    lines.push(
      `Planned models (not execution evidence):\n${execution.plannedModels
        .map(
          (phase) => `- ${phase.role}: ${phase.model}${phase.phaseId ? ` (${phase.phaseId})` : ""}`,
        )
        .join("\n")}`,
    );
  add("Requested model", execution.requestedModel);
  add("Resolved virtual model", execution.syntheticModel);
  add(
    "Requested routing",
    execution.requestedProviderDefault ? "provider default" : execution.requestedPreference,
  );
  add(
    "Effective routing",
    execution.effectivePreference ??
      (execution.requestedProviderDefault && execution.status === "effective"
        ? "provider default"
        : undefined),
  );
  add("Pending routing", execution.pendingPreference);
  add("Activating routing", execution.activatingPreference);
  add(
    execution.startedAt ? `Started (${execution.startSource})` : "Start",
    execution.startedAt ?? execution.startSource,
  );
  add("Ended", execution.endedAt);
  add(
    "Provider elapsed",
    execution.durationMs === undefined ? "not reported" : formatDuration(execution.durationMs),
  );
  add(
    execution.kind === "selection"
      ? "Snapshot time"
      : execution.kind === "gap"
        ? "Gap detected"
        : "Provider event time",
    execution.sourceTimestamp,
  );
  add("Received", execution.receivedAt);
  add("Planned fallback model (not execution evidence)", execution.fallbackModel);
  add("Degraded to phase", execution.degradedToPhaseId);
  add("Final source model", execution.finalSourceModel);
  add("Final source phase", execution.finalSourcePhaseId);
  add("Reason", execution.reason);
  if (execution.awaitingBackgroundWork !== undefined) {
    add(
      "Background work",
      execution.awaitingBackgroundWork ? "awaiting completion" : "not pending",
    );
  }
  if (execution.endedWithBackgroundWork !== undefined)
    add("Phase ended with background work", execution.endedWithBackgroundWork ? "yes" : "no");
  add("Session", execution.nativeSessionId);
  add("Turn", execution.nativeTurnId);
  add("Fusion", execution.fusionId);
  add("Phase", execution.phaseId);
  add("Event", execution.eventId);
  add("Contract version", execution.contractVersion);
  if (execution.gaps.length > 0)
    lines.push(`Telemetry gaps:\n${execution.gaps.map((gap) => `- ${gap}`).join("\n")}`);
  return lines.join("\n");
}

import * as Effect from "effect/Effect";
import * as Schema from "effect/Schema";
import * as SchemaTransformation from "effect/SchemaTransformation";
import { TrimmedNonEmptyString } from "./baseSchemas.ts";
import { ProviderDriverKind } from "./providerInstance.ts";

export const ProviderOptionDescriptorType = Schema.Literals(["select", "boolean"]);
export type ProviderOptionDescriptorType = typeof ProviderOptionDescriptorType.Type;

export const ProviderOptionChoice = Schema.Struct({
  id: TrimmedNonEmptyString,
  label: TrimmedNonEmptyString,
  description: Schema.optional(TrimmedNonEmptyString),
  disabledReason: Schema.optional(TrimmedNonEmptyString),
  isDefault: Schema.optional(Schema.Boolean),
  /** A select choice that dispatches false to explicitly reset the provider preference. */
  isReset: Schema.optional(Schema.Boolean),
});
export type ProviderOptionChoice = typeof ProviderOptionChoice.Type;

const ProviderOptionDescriptorBase = {
  id: TrimmedNonEmptyString,
  label: TrimmedNonEmptyString,
  description: Schema.optional(TrimmedNonEmptyString),
} as const;

export const SelectProviderOptionDescriptor = Schema.Struct({
  ...ProviderOptionDescriptorBase,
  type: Schema.Literal("select"),
  options: Schema.Array(ProviderOptionChoice),
  currentValue: Schema.optional(TrimmedNonEmptyString),
  promptInjectedValues: Schema.optional(Schema.Array(TrimmedNonEmptyString)),
});
export type SelectProviderOptionDescriptor = typeof SelectProviderOptionDescriptor.Type;

export const BooleanProviderOptionDescriptor = Schema.Struct({
  ...ProviderOptionDescriptorBase,
  type: Schema.Literal("boolean"),
  currentValue: Schema.optional(Schema.Boolean),
});
export type BooleanProviderOptionDescriptor = typeof BooleanProviderOptionDescriptor.Type;

export const ProviderOptionDescriptor = Schema.Union([
  SelectProviderOptionDescriptor,
  BooleanProviderOptionDescriptor,
]);
export type ProviderOptionDescriptor = typeof ProviderOptionDescriptor.Type;

export const ProviderOptionSelectionValue = Schema.Union([TrimmedNonEmptyString, Schema.Boolean]);
export type ProviderOptionSelectionValue = typeof ProviderOptionSelectionValue.Type;

export const ProviderOptionSelection = Schema.Struct({
  id: TrimmedNonEmptyString,
  value: ProviderOptionSelectionValue,
});
export type ProviderOptionSelection = typeof ProviderOptionSelection.Type;

const LegacyProviderOptionSelectionsObject = Schema.Record(Schema.String, Schema.Unknown);

const ProviderOptionSelectionsFromLegacyObject = LegacyProviderOptionSelectionsObject.pipe(
  Schema.decodeTo(
    Schema.Array(ProviderOptionSelection),
    SchemaTransformation.transformEffect({
      decode: (record) => Effect.succeed(coerceLegacyOptionsObjectToArray(record)),
      encode: (selections) => Effect.succeed(canonicalSelectionsToLegacyObject(selections)),
    }),
  ),
);

export const ProviderOptionSelections = Schema.Union([
  Schema.Array(ProviderOptionSelection),
  ProviderOptionSelectionsFromLegacyObject,
]);
export type ProviderOptionSelections = typeof ProviderOptionSelections.Type;

function coerceLegacyOptionsObjectToArray(
  record: Record<string, unknown>,
): ReadonlyArray<ProviderOptionSelection> {
  const entries: Array<ProviderOptionSelection> = [];
  for (const [rawKey, rawValue] of Object.entries(record)) {
    const id = typeof rawKey === "string" ? rawKey.trim() : "";
    if (id.length === 0) continue;
    if (typeof rawValue === "string") {
      const trimmed = rawValue.trim();
      if (trimmed.length > 0) entries.push({ id, value: trimmed });
    } else if (typeof rawValue === "boolean") {
      entries.push({ id, value: rawValue });
    }
  }
  return entries;
}

function canonicalSelectionsToLegacyObject(
  selections: ReadonlyArray<ProviderOptionSelection>,
): Record<string, string | boolean> {
  const out: Record<string, string | boolean> = {};
  for (const { id, value } of selections) {
    out[id] = value;
  }
  return out;
}

export const ModelCapabilities = Schema.Struct({
  optionDescriptors: Schema.optional(Schema.Array(ProviderOptionDescriptor)),
});
export type ModelCapabilities = typeof ModelCapabilities.Type;

export const CustomModelEntry = Schema.Struct({
  slug: TrimmedNonEmptyString,
  name: Schema.optional(TrimmedNonEmptyString),
  capabilities: Schema.optional(ModelCapabilities),
});
export type CustomModelEntry = typeof CustomModelEntry.Type;

export const CustomModelSetting = Schema.Union([Schema.String, CustomModelEntry]);
export type CustomModelSetting = typeof CustomModelSetting.Type;

const CODEX_DRIVER_KIND = ProviderDriverKind.make("codex");
const CLAUDE_DRIVER_KIND = ProviderDriverKind.make("claudeAgent");
const CURSOR_DRIVER_KIND = ProviderDriverKind.make("cursor");
const GROK_DRIVER_KIND = ProviderDriverKind.make("grok");
const FX_DRIVER_KIND = ProviderDriverKind.make("fx");
const MUSE_DRIVER_KIND = ProviderDriverKind.make("muse");
const PI_DRIVER_KIND = ProviderDriverKind.make("pi");
const ACP_REGISTRY_DRIVER_KIND = ProviderDriverKind.make("acpRegistry");
const OPENCODE_DRIVER_KIND = ProviderDriverKind.make("opencode");

export const DEFAULT_MODEL = "gpt-6-astra";

/** First model present in model/list wins; otherwise use Codex's isDefault. */
export const PREFERRED_DEFAULT_CODEX_MODELS: ReadonlyArray<string> = [
  DEFAULT_MODEL,
  "gpt-5.6-sol",
  "gpt-5.6-terra",
];
export const DEFAULT_TEXT_GENERATION_MODEL = "gpt-6-luna";
/** Keep the official Antigravity session's current model. Never send this ID to ACP. */
export const ANTIGRAVITY_DEFAULT_MODEL = "antigravity-default";
export const DEFAULT_TEXT_GENERATION_REASONING_EFFORT = "low";

/** Let Muse pick the account's default model. Never send this ID to Muse. */
export const MUSE_DEFAULT_MODEL = "default";

export const DEFAULT_MODEL_BY_PROVIDER: Partial<Record<ProviderDriverKind, string>> = {
  [CODEX_DRIVER_KIND]: DEFAULT_MODEL,
  [CLAUDE_DRIVER_KIND]: "claude-opus-5-5",
  [CURSOR_DRIVER_KIND]: "auto",
  // Product slug meaning the current session model, never an ACP model id.
  [GROK_DRIVER_KIND]: "grok-build",
  [FX_DRIVER_KIND]: "default",
  [MUSE_DRIVER_KIND]: MUSE_DEFAULT_MODEL,
  [ACP_REGISTRY_DRIVER_KIND]: "default",
  // "default" defers to the user's own Pi settings.json model selection.
  [PI_DRIVER_KIND]: "default",
  [OPENCODE_DRIVER_KIND]: "openai/gpt-5",
  [ProviderDriverKind.make("antigravity")]: ANTIGRAVITY_DEFAULT_MODEL,
};

export const DEFAULT_TEXT_GENERATION_MODEL_BY_PROVIDER: Partial<
  Record<ProviderDriverKind, string>
> = {
  [CODEX_DRIVER_KIND]: DEFAULT_TEXT_GENERATION_MODEL,
  [ProviderDriverKind.make("antigravity")]: ANTIGRAVITY_DEFAULT_MODEL,
  [CLAUDE_DRIVER_KIND]: "claude-haiku-5-5",
  [CURSOR_DRIVER_KIND]: "composer-2",
