    content: "PRIVATE",
    verdict: null,
    usage: { inputTokens: 10, outputTokens: 5, cachedTokens: 0, requestCount: 1, totalNanoAiu: 0 },
  },
});

function promiseGate() {
  let resolve!: () => void;
  const promise = new Promise<void>((done) => {
    resolve = done;
  });
  return { promise, resolve };
}

const setup = Effect.fnUntraced(function* (
  fake: Fake,
  initialNativeThreadId?: string,
  initialSelection: ModelSelection = selection,
  runtimeSessionId = sessionId,
) {
  const adapter = yield* makeAdapter(
    { instanceId, settings, environment: { HOME: "/test-account" } },
    { clientFactory: () => fake.client },
  );
  const runtime = yield* adapter.openSession({
    threadId,
    providerSessionId: runtimeSessionId,
    modelSelection: initialSelection,
    runtimePolicy: policy,
    ...(initialNativeThreadId ? { initialNativeThreadId } : {}),
  });
  const emitted: ProviderAdapter.ProviderAdapterV2Event[] = [];
  const eventQueue = yield* Queue.unbounded<ProviderAdapter.ProviderAdapterV2Event>();
  yield* runtime.events.pipe(
    Stream.runForEach((event) =>
      Effect.sync(() => {
        emitted.push(event);
      }).pipe(Effect.andThen(Queue.offer(eventQueue, event))),
    ),
    Effect.forkScoped,
  );
  const takeEvent = Effect.fnUntraced(function* (
    predicate: (event: ProviderAdapter.ProviderAdapterV2Event) => boolean,
  ) {
    while (true) {
      const event = yield* Queue.take(eventQueue);
      if (predicate(event)) return event;
    }
  });
  const thread = yield* runtime.ensureThread({
    threadId,
    modelSelection: initialSelection,
    runtimePolicy: policy,
  });
  const start = Effect.fnUntraced(function* (ordinal = 1, turnSelection = initialSelection) {
    const now = yield* DateTime.now;
    const appThread: OrchestrationV2AppThread = {
      id: threadId,
      projectId: ProjectId.make("project"),
      title: "Test",
      providerInstanceId: instanceId,
      modelSelection: turnSelection,
      runtimeMode: policy.runtimeMode,
      interactionMode: "default",
      branch: null,
      worktreePath: null,
      activeProviderThreadId: thread.id,
      lineage: { parentThreadId: null, relationshipToParent: null, rootThreadId: threadId },
      forkedFrom: null,
      createdBy: "user",
      creationSource: "web",
      createdAt: now,
      updatedAt: now,
      archivedAt: null,
      settledOverride: null,
      settledAt: null,
      lastVisitedAt: null,
      deletedAt: null,
    };
    yield* runtime.startTurn({
      appThread,
      threadId,
      runId: RunId.make(`run-${ordinal}`),
      runOrdinal: ordinal,
      providerTurnOrdinal: ordinal,
      attemptId: RunAttemptId.make(`attempt-${ordinal}`),
      rootNodeId: NodeId.make(`root-${ordinal}`),
      providerThread: thread,
      message: {
        messageId: MessageId.make(`user-${ordinal}`),
        text: "Hello",
        attachments: [],
        createdBy: "user",
        creationSource: "web",
      },
      modelSelection: turnSelection,
      runtimePolicy: policy,
    });
  });
  const drain = () => runtime.readThreadSnapshot({ providerThread: thread });
  return { runtime, thread, emitted, start, drain, takeEvent };
});

const provide = <A, E, R>(effect: Effect.Effect<A, E, R>) =>
  effect.pipe(
    Effect.provideService(ProviderHost.ProviderHost, host),
    Effect.provide(McpProviderSessions.layer),
    Effect.scoped,
  );

describe("native Copilot V2", () => {
  it.effect.each(["single", "cascade", "critique"])(
    "publishes only committed root %s output before late plan telemetry",
    (pattern) =>
      provide(
        Effect.gen(function* () {
          const fake = fakeSdk();
          const autoSelection: ModelSelection = {
            instanceId,
            model: "auto",
            options: [{ id: "autoTier", value: "opaque-high" }],
          };
          fake.setCatalog({
            models: [],
            auto: {
              defaultTier: "opaque-high",
              tiers: [
                {
                  id: "opaque-high",
                  displayName: "High",
                  description: "",
                  type: "fusion",
                  status: { enabled: true },
                },
              ],
            },
          });
          const { start, drain, emitted, takeEvent } = yield* setup(fake, undefined, autoSelection);
          yield* start();
          const fusion = {
            fusionId: "fusion-1",
            phaseId: "solver",
            sourceModel: "solver-model",
            pattern,
            role: "solver",
            conversationScope: "root",
          };
          fake.emit("assistant.message_delta", {
            messageId: "answer",
            deltaContent: "DISCARDED DRAFT",
          });
          fake.emit("assistant.reasoning_delta", {
            reasoningId: "reason",
            deltaContent: "PRIVATE",
          });
          fake.emit("assistant.reasoning", { reasoningId: "reason", content: "PRIVATE" });
          fake.emit("assistant.message", {
            messageId: "answer",
            content: "DISCARDED DRAFT",
            fusion,
          });
          assert.equal((yield* drain()).messages.length, 0);
          assert.isFalse(emitted.some((event) => event.type === "message.updated"));
          fake.emit("assistant.message", {
            messageId: "review",
            content: "PRIVATE REVIEW",
            fusion: { ...fusion, commitId: "review-commit", conversationScope: "review" },
          });
          fake.emit("assistant.message", {
            messageId: "answer",
            content: "Correct final answer",
            originatingMessageId: "native-user-message-1",
            fusion: { ...fusion, commitId: "final-commit" },
          });
          fake.emit("session.fusion_resolved", {
            fusionId: "fusion-1",
            turnId: "different-native-namespace",
            primaryModel: "solver-model",
            fallbackModel: "fallback-model",
            contractVersion: 1,
            syntheticModel: "opaque-high",
            policy: "standard",
            pattern,
          });
          fake.emit("assistant.message", {
            messageId: "answer",
            content: "Correct final answer",
            fusion: { ...fusion, commitId: "final-commit" },
          });
          const route = yield* takeEvent(
            (event) =>
              event.type === "turn_item.updated" &&
              event.turnItem.type === "system_notice" &&
              event.turnItem.modelExecution?.fusionId === "fusion-1" &&
              event.turnItem.runId === RunId.make("run-1"),
          );
          const snapshot = yield* drain();
          assert.deepEqual(
            snapshot.messages.map((message) => message.text),
            ["Correct final answer"],
          );
          assert.isFalse(snapshot.messages[0]!.streaming);
          assert.ok(route.type === "turn_item.updated");
          if (route.type === "turn_item.updated")
            assert.equal(route.turnItem.runId, RunId.make("run-1"));
          assert.isFalse(
            emitted.some(
              (event) => event.type === "turn_item.updated" && event.turnItem.type === "reasoning",
            ),
          );
        }),
      ),
  );

  it.effect(
    "backfills Fusion ownership when its root message precedes the native send acknowledgement",
    () =>
      provide(
        Effect.gen(function* () {
          const fake = fakeSdk();
          const gate = promiseGate();
          fake.session.send = async () => {
            fake.emit("assistant.message", {
              messageId: "answer",
              originatingMessageId: "late-ack",
              content: "Correct final answer",
              fusion: {
                fusionId: "fusion-1",
                phaseId: "solver",
                conversationScope: "root",
                commitId: "commit",
              },
            });
            fake.emit("session.fusion_resolved", {
              fusionId: "fusion-1",
              turnId: "synthetic-turn",
              primaryModel: "solver-model",
              fallbackModel: "fallback-model",
              contractVersion: 1,
              syntheticModel: "opaque-high",
              policy: "standard",
              pattern: "single",
            });
            await gate.promise;
            return "late-ack";
          };
          const { start, drain, takeEvent } = yield* setup(fake);
          const running = yield* Effect.forkChild(start());
          yield* takeEvent(
            (event) =>
              event.type === "turn_item.updated" &&
              event.turnItem.type === "system_notice" &&
              event.turnItem.modelExecution?.fusionId === "fusion-1" &&
              event.turnItem.runId === null,
          );
          assert.equal((yield* drain()).messages.length, 0);
          gate.resolve();
          yield* Fiber.join(running);
          const route = yield* takeEvent(
            (event) =>
              event.type === "turn_item.updated" &&
              event.turnItem.type === "system_notice" &&
              event.turnItem.modelExecution?.fusionId === "fusion-1" &&
