          if (skills._tag === "Success")
            options.onSkills?.(cwd, skillsFromSdk(skills.success.skills as SkillsLoadedSkill[]));
          yield* drain();
          return createdThread;
        });
      const startTurn: ProviderAdapter.ProviderAdapterV2SessionRuntime["startTurn"] = Effect.fn(
        "CopilotAdapter.startTurn",
      )(function* (turnInput) {
        if (
          !native ||
          !providerThread ||
          stopped ||
          alreadyInUse ||
          turnInput.modelSelection.instanceId !== input.instanceId
        )
          return yield* new ProviderAdapter.ProviderAdapterTurnStartError({
            driver: COPILOT_DRIVER,
            providerThreadId: turnInput.providerThread.id,
            threadId: turnInput.threadId,
            runId: turnInput.runId,
          });
        if (active && !active.finished)
          return yield* new ProviderAdapter.ProviderAdapterProtocolError({
            driver: COPILOT_DRIVER,
            detail: "Previous Copilot turn is still active",
            reason: "previous_turn_active",
          });
        const effort = reasoningEffort(turnInput.modelSelection);
        const autoCatalog =
          turnInput.modelSelection.model === "auto"
            ? yield* sdk("list routing choices", async () => (await native!.rpc.model.list()).auto)
            : undefined;
        const autoTier = yield* sdk("validate model selection", async () =>
          autoTierForSelection(turnInput.modelSelection, autoCatalog),
        );
        yield* sdk("set model", () =>
          native!.setModel(turnInput.modelSelection.model, {
            ...(effort ? { reasoningEffort: effort } : {}),
            ...(autoTier !== undefined ? { autoTier } : {}),
          }),
        );
        const modeResult = yield* sdk("set mode", () =>
          native!.rpc.mode.set({
            mode: turnInput.runtimePolicy.interactionMode === "plan" ? "plan" : "interactive",
          }),
        );
        if (modeResult.modeApplied === false || modeResult.deferImplementation === true) {
          return yield* new ProviderAdapter.ProviderAdapterProtocolError({
            driver: COPILOT_DRIVER,
            detail: "Copilot did not apply the requested interaction mode.",
          });
        }
        yield* drain();
        const now = yield* DateTime.now;
        const providerTurn: OrchestrationV2ProviderTurn = {
          id: ProviderTurnId.make(
            `${providerThread.id}:${turnInput.attemptId}:${turnInput.providerTurnOrdinal}`,
          ),
          providerThreadId: providerThread.id,
          nodeId: turnInput.rootNodeId,
          runAttemptId: turnInput.attemptId,
          nativeTurnRef: null,
          ordinal: turnInput.providerTurnOrdinal,
          status: "running",
          startedAt: now,
          completedAt: null,
        };
        const turn: ActiveTurn = {
          input: turnInput,
          providerTurn,
          nextOrdinal: 1,
          items: new Map(),
          fusionText: autoCatalog?.tiers.some((tier) => tier.type === "fusion") === true,
          accepted: false,
          idle: false,
          interrupted: false,
          finished: false,
        };
        active = turn;
        lastTurn = turn;
        turns.set(providerTurn.id, providerTurn);
        yield* emit({
          type: "provider_turn.updated",
          driver: COPILOT_DRIVER,
          threadId: open.threadId,
          providerTurn,
        });
        yield* updateThread({
          status: "active",
          firstRunOrdinal: providerThread.firstRunOrdinal ?? turnInput.runOrdinal,
          lastRunOrdinal: turnInput.runOrdinal,
          nativeMetadata: {
            ...providerThread.nativeMetadata,
            modelSelection: turnInput.modelSelection,
          },
        });
        if (turnInput.modelSelection.model === "auto")
          yield* refreshSelection(turnInput.modelSelection, turn);
        const userText = yield* providerMessageTextWithAttachmentPaths({
          text: turnInput.message.text,
          attachments: turnInput.message.attachments,
          resolveAttachmentPath: host.resolveAttachmentPath,
        });
        const instructions = buildRuntimeInstructions({
          harness: "GitHub Copilot",
          model: turnInput.modelSelection.model,
          reasoningEffort: effort,
        });
        const context = turnInput.appContext?.map((entry) => entry.text).join("\n\n") ?? "";
        const prompt = [instructions, history, context, userText].filter(Boolean).join("\n\n");
        const attachments: NonNullable<MessageOptions["attachments"]> = [];
        for (const attachment of turnInput.message.attachments) {
          const path = host.resolveAttachmentPath(attachment);
          if (!path)
            return yield* new ProviderAdapter.ProviderAdapterProtocolError({
              driver: COPILOT_DRIVER,
              detail: "Copilot attachment is unavailable",
              reason: "attachment_unreadable",
            });
          attachments.push({ type: "file" as const, path, displayName: attachment.name });
        }
        history = "";
        const nativeMessageId = yield* sdk(
          "send",
          () =>
            native!.send({
              prompt,
              mode: "immediate",
              agentMode:
                turnInput.runtimePolicy.interactionMode === "plan" ? "plan" : "interactive",
              ...(attachments.length ? { attachments } : {}),
            }),
          30_000,
        ).pipe(
          Effect.tapError(() =>
            Effect.sync(() => {
              active = undefined;
            }),
          ),
        );
        nativeMessageOwners.set(nativeMessageId, turn);
        if (nativeMessageOwners.size > MAX_EXECUTION_ITEMS)
          nativeMessageOwners.delete(nativeMessageOwners.keys().next().value!);
        for (const [fusionId, origin] of pendingFusionOrigins) {
          if (origin === nativeMessageId) {
            pendingFusionOrigins.delete(fusionId);
            yield* bindFusionOwner(fusionId, turn);
          }
        }
        for (const [messageId, message] of pendingFusionMessages) {
          if (message.origin === nativeMessageId) {
            pendingFusionMessages.delete(messageId);
            yield* textEvent(turn, messageId, message.content, true, false);
          }
        }
        turn.accepted = true;
        yield* Queue.offer(inbox, { type: "accepted" });
      });
      return {
        instanceId: input.instanceId,
        driver: COPILOT_DRIVER,
        providerSessionId: open.providerSessionId,
        providerSession,
        events: Stream.fromQueue(events),
        hasPendingBackgroundWork: Effect.sync(() =>
          [...tasks.values()].some((task) => task.status === "running" || task.status === "idle"),
        ),
        ensureThread,
        resumeThread: (resume) =>
          ensureThread({
            threadId: resume.threadId ?? open.threadId,
            existingProviderThread: resume.providerThread,
            modelSelection: resume.modelSelection ?? open.modelSelection,
            runtimePolicy: resume.runtimePolicy ?? open.runtimePolicy,
          }),
        injectHistory: (context) =>
          Effect.sync(() => {
            history = context.context;
            return true;
          }),
        startTurn,
        steerTurn: (steer) =>
          Effect.fail(
            new ProviderAdapter.ProviderAdapterSteerRunUnsupportedError({
              driver: COPILOT_DRIVER,
              providerThreadId: steer.providerThread.id,
            }),
          ),
        interruptTurn: Effect.fn("CopilotAdapter.interruptTurn")(function* () {
          if (!native || !active) return;
          active.interrupted = true;
          yield* sdk("abort", () => native!.abort());
        }),
        stopTask: ({ taskId }) =>
          sdk("cancel task", () => native!.rpc.tasks.cancel({ id: taskId })).pipe(Effect.asVoid),
        respondToRuntimeRequest: Effect.fn("CopilotAdapter.respondToRuntimeRequest")(
          function* (response) {
            const entry = pending.get(response.requestId);
            const permissionReplyKey = `${response.decision ?? ""}\n${response.feedback ?? ""}`;
            if (
              !entry &&
              confirmedPermissionReplies.get(response.requestId) === permissionReplyKey &&
              response.answers === undefined
            )
              return;
            if (!entry)
              return yield* new ProviderAdapter.ProviderAdapterRuntimeRequestResponseError({
                driver: COPILOT_DRIVER,
                requestId: response.requestId,
              });
            const answer = response.answers?.answer;
            const validAnswer =
              typeof answer === "string" ||
              (Array.isArray(answer) && answer.every((part) => typeof part === "string"));
            if (
              entry.request.kind === "user_input"
                ? !validAnswer
                : !["accept", "decline", "cancel"].includes(response.decision ?? "") ||
                  response.answers !== undefined
            ) {
              return yield* new ProviderAdapter.ProviderAdapterRuntimeRequestResponseError({
                driver: COPILOT_DRIVER,
                requestId: response.requestId,
                cause: new Error(
                  "Copilot requires a supported one-time decision or a text answer.",
                ),
              });
            }
            if (entry.responseOwnedByV2) {
              if (!entry.nativePermissionId || entry.permissionReplyKey !== permissionReplyKey) {
                return yield* new ProviderAdapter.ProviderAdapterRuntimeRequestResponseError({
                  driver: COPILOT_DRIVER,
                  requestId: response.requestId,
                });
              }
              if (entry.permissionReplyReceipt)
                return yield* Deferred.await(entry.permissionReplyReceipt);
            }
            // V2 already recorded the answer. Ownership must survive even a failed native receipt.
            entry.responseOwnedByV2 = true;
            const receipt = Deferred.makeUnsafe<void, ProviderAdapter.ProviderAdapterV2Error>();
            if (entry.nativePermissionId) {
              entry.permissionReplyKey = permissionReplyKey;
              entry.permissionReplyReceipt = receipt;
            }
            return yield* Effect.gen(function* () {
              const now = yield* DateTime.now;
              if (entry.nativePermissionId) {
                yield* decidePermission(
                  entry.nativePermissionId,
                  response.decision === "accept"
                    ? { kind: "approve-once" }
                    : {
                        kind: "reject",
                        ...(response.feedback ? { feedback: response.feedback } : {}),
                      },
                );
                confirmedPermissionReplies.set(response.requestId, permissionReplyKey);
              }
              pending.delete(response.requestId);
              entry.owner.items.set(response.requestId, {
                ...entry.item,
                status: "completed",
                completedAt: now,
                updatedAt: now,
              });
              // The decider owns resolution and delivery state; callback handoff is the last operation.
              if (!entry.nativePermissionId) entry.resolve(response);
            }).pipe(
              Effect.onExit((exit) => {
                delete entry.permissionReplyReceipt;
                return Deferred.done(receipt, exit);
              }),
            );
          },
        ),
        readThreadSnapshot: Effect.fn("CopilotAdapter.readThreadSnapshot")(function* () {
          yield* drain();
          if (!providerThread)
            return yield* new ProviderAdapter.ProviderAdapterProtocolError({
              driver: COPILOT_DRIVER,
              detail: "Copilot thread is not loaded",
            });
          return {
            providerThread,
            providerTurns: [...turns.values()],
            messages: [...messages.values()],
            runtimeRequests: [...pending.values()]
              .filter((entry) => !entry.responseOwnedByV2)
              .map((entry) => entry.request),
          };
        }),
        rollbackThread: (rollback) =>
          Effect.fail(
            new ProviderAdapter.ProviderAdapterRollbackThreadError({
              driver: COPILOT_DRIVER,
              providerThreadId: rollback.providerThread.id,
              cause: new Error("Native Copilot rollback is unsupported."),
            }),
          ),
        forkThread: (fork) =>
          Effect.fail(
            new ProviderAdapter.ProviderAdapterForkThreadError({
              driver: COPILOT_DRIVER,
              providerThreadId: fork.sourceProviderThread.id,
              cause: new Error("Native Copilot fork is unsupported."),
            }),
          ),
      } satisfies ProviderAdapter.ProviderAdapterV2SessionRuntime;
    }),
  });
});

// @effect-diagnostics nodeBuiltinImport:off
import * as NodeModule from "node:module";
import * as NodeOS from "node:os";
import * as NodePath from "node:path";
import * as NodeFS from "node:fs";
import * as NodeSea from "node:sea";
import type { CopilotClient, CopilotClientOptions } from "@github/copilot-sdk";
import type { CopilotSettings } from "../settings.ts";

const require = NodeModule.createRequire(import.meta.url);

export const createClient = (options: CopilotClientOptions): CopilotClient =>
  new (require("@github/copilot-sdk") as typeof import("@github/copilot-sdk")).CopilotClient(
    options,
  );

export interface HostRuntime {
  readonly packaged: boolean;
  readonly electron: boolean;
  readonly platform: string;
  readonly architecture: string;
  readonly resolve: (name: string) => string;
  readonly exists: (path: string) => boolean;
}

function hostRuntime(): HostRuntime {
  return {
    packaged: typeof process.versions.electron === "string" || NodeSea.isSea(),
    electron: typeof process.versions.electron === "string",
    // oxlint-disable-next-line t3code/no-global-process-runtime -- SDK options are synchronous; tests inject the host descriptor.
    platform: NodeOS.platform(),
    // oxlint-disable-next-line t3code/no-global-process-runtime -- SDK options are synchronous; tests inject the host descriptor.
    architecture: NodeOS.arch(),
    resolve: (name) =>
      NodeModule.createRequire(require.resolve("@github/copilot-sdk")).resolve(name),
    exists: NodeFS.existsSync,
  };
}

export function bundledCliPath(runtime: HostRuntime): string | undefined {
  if (!runtime.packaged) return undefined;
  if (
    !["darwin", "linux", "win32"].includes(runtime.platform) ||
    !["arm64", "x64"].includes(runtime.architecture)
  ) {
    throw new Error("Unsupported GitHub Copilot runtime platform.");
  }
  for (const platform of runtime.platform === "linux"
    ? ["linux", "linuxmusl"]
    : [runtime.platform]) {
    try {
      const target = `${platform}-${runtime.architecture}`;
      const manifest = runtime.resolve(`@github/copilot-sdk-${target}/package.json`);
      const paths = runtime.platform === "win32" ? NodePath.win32 : NodePath.posix;
      const path = paths.join(
        paths.dirname(manifest),
        "prebuilds",
        target,
        runtime.platform === "win32" ? "copilot-runtime.exe" : "copilot-runtime",
      );
      const executable = runtime.electron
        ? path.replace(/([\\/][^\\/]+\.asar)(?=[\\/])/u, "$1.unpacked")
        : path;
      if (
        runtime.exists(executable) &&
        runtime.exists(paths.join(paths.dirname(executable), "runtime.node"))
      )
        return executable;
    } catch {
      /* The Linux libc variant may not be installed. */
    }
  }
  throw new Error("The bundled GitHub Copilot executable is unavailable.");
}

export function resolveClientConfiguration(
  input: {
    readonly settings: CopilotSettings;
    readonly cwd: string;
    readonly environment: NodeJS.ProcessEnv;
  },
  runtime: HostRuntime = hostRuntime(),
): { readonly options: CopilotClientOptions; readonly effectiveHome: string } {
  const { settings, environment } = input;
  const hostHome = environment.HOME || environment.USERPROFILE || NodeOS.homedir();
  const configuredHome =
    settings.homePath.trim() ||
    environment.COPILOT_HOME?.trim() ||
    NodePath.join(hostHome, ".copilot");
  const expandedHome =
    configuredHome === "~"
      ? hostHome
      : /^~[/\\]/u.test(configuredHome)
        ? NodePath.join(hostHome, configuredHome.slice(2))
        : configuredHome;
  const effectiveHome = NodePath.resolve(expandedHome);
  const binaryPath = settings.binaryPath?.trim();
  const configured =
    binaryPath && !/^copilot(?:\.(?:exe|cmd|bat))?$/iu.test(binaryPath) ? binaryPath : undefined;
  const connection = environment.COPILOT_SDK_DEFAULT_CONNECTION?.trim().toLowerCase();
  const bundled =
    !configured && !environment.COPILOT_CLI_PATH?.trim() && (!connection || connection === "stdio")
      ? bundledCliPath(runtime)
      : undefined;
  const override = configured ?? bundled;
  const fusionEnvironment = settings.enableFusion
    ? {
        COPILOT_CLI_ENABLED_FEATURE_FLAGS: [
          ...new Set([
            ...(environment.COPILOT_CLI_ENABLED_FEATURE_FLAGS ?? "")
              .split(",")
              .map((flag) => flag.trim())
              .filter(Boolean),
            "DYNAMIC_AUTO_TIERS",
            "HYDRAFUSION_PLAN_V2",
          ]),
        ].join(","),
      }
    : {};
  return {
    effectiveHome,
    options: {
      mode: "copilot-cli",
      workingDirectory: input.cwd,
      baseDirectory: effectiveHome,
      env: { ...environment, ...fusionEnvironment, COPILOT_HOME: effectiveHome },
      logLevel: "error",
      ...(override
        ? {
            connection: (
              require("@github/copilot-sdk") as typeof import("@github/copilot-sdk")
            ).RuntimeConnection.forStdio({ path: override }),
          }
        : {}),
    },
  };
}

import { assert, describe, it } from "@effect/vitest";
import { ProviderInstanceId } from "@t3tools/contracts";
import { autoTierForSelection, routingDescriptor, type AutoCatalog } from "./routing.ts";

const instanceId = ProviderInstanceId.make("account-a");
export const autoCatalog: AutoCatalog = {
  defaultTier: "standard",
  tiers: [
    {
      id: "standard",
      displayName: "Standard",
      description: "",
      type: "auto",
      status: { enabled: true },
    },
    {
      id: "fuse@2026:opaque",
      displayName: "Fusion",
      description: "Account routing",
      type: "fusion",
      fusionTier: "do-not-translate",
      status: { enabled: true },
    },
    {
      id: "blocked",
      displayName: "Unavailable",
      description: "",
      type: "fusion",
      status: { enabled: false, message: "Your account policy disables this." },
    },
    {
      id: "hidden",
      displayName: "Hidden",
      description: "",
      type: "fusion",
      status: { enabled: true, pickerVisible: false },
    },
  ],
};

describe("account-advertised routing", () => {
  it("distinguishes an explicit provider-default reset from an omitted preference", () => {
    assert.isNull(
      autoTierForSelection({
        instanceId,
        model: "auto",
        options: [{ id: "autoTier", value: false }],
      }),
    );
    assert.isUndefined(autoTierForSelection({ instanceId, model: "auto" }));
    assert.throws(
      () =>
        autoTierForSelection({
          instanceId,
          model: "auto",
          options: [{ id: "autoTier", value: true }],
        }),
      /advertised tier/,
    );
    const descriptor = routingDescriptor({
      ...autoCatalog,
      tiers: [...autoCatalog.tiers, { ...autoCatalog.tiers[0]!, id: "provider-default" }],
    });
    assert.equal(descriptor.options.at(-1)?.id, "_provider-default");
    assert.isTrue(descriptor.options.at(-1)?.isReset);
  });
  it("uses opaque IDs without aliases, honors visibility, and exposes disabled reasons", () => {
    const descriptor = routingDescriptor(autoCatalog);
    assert.deepEqual(
      descriptor.options.map((option) => option.id),
      ["standard", "fuse@2026:opaque", "blocked", "provider-default"],
    );
    assert.equal(descriptor.options[2]?.disabledReason, "Your account policy disables this.");
    assert.equal(descriptor.currentValue, "standard");
    const selection = {
      instanceId,
      model: "auto",
      options: [{ id: "autoTier", value: "fuse@2026:opaque" }],
    };
    assert.equal(autoTierForSelection(selection, autoCatalog), "fuse@2026:opaque");
    assert.isUndefined(autoTierForSelection({ instanceId, model: "auto" }, autoCatalog));
    assert.isUndefined(autoTierForSelection({ instanceId, model: "explicit" }));
  });

  it("refuses unknown, hidden, policy-disabled and unsupported destination choices", () => {
    for (const id of ["blocked", "hidden", "unknown"])
      assert.throws(() =>
        autoTierForSelection(
          {
            instanceId,
            model: "auto",
            options: [{ id: "autoTier", value: id }],
          },
          autoCatalog,
        ),
      );
    assert.throws(
      () =>
        autoTierForSelection({
          instanceId,
          model: "auto",
          options: [{ id: "autoTier", value: "fuse@2026:opaque" }],
        }),
      /does not advertise/,
    );
    assert.throws(
      () =>
        autoTierForSelection(
          {
            instanceId,
            model: "explicit",
            options: [{ id: "autoTier", value: "standard" }],
          },
          autoCatalog,
        ),
      /requires/,
    );
  });
  it("leaves plain Auto routing to the runtime without requiring an advertised default tier", () => {
    const selection = { instanceId, model: "auto" };
    assert.isUndefined(autoTierForSelection(selection));
    assert.isUndefined(autoTierForSelection(selection, { defaultTier: "unknown", tiers: [] }));
    assert.isUndefined(autoTierForSelection(selection, { ...autoCatalog, defaultTier: "blocked" }));
  });
});

import type { CopilotClient } from "@github/copilot-sdk";
import type {
  ModelSelection,
  ProviderOptionChoice,
  SelectProviderOptionDescriptor,
} from "@t3tools/contracts";
import { getProviderOptionStatedValue } from "@t3tools/shared/model";

export type ModelCatalog = Awaited<ReturnType<CopilotClient["rpc"]["models"]["list"]>>;
export type AutoCatalog = NonNullable<ModelCatalog["auto"]>;

export function routingDescriptor(auto: AutoCatalog): SelectProviderOptionDescriptor {
  const seen = new Set<string>();
  const options: Array<ProviderOptionChoice> = auto.tiers.flatMap((tier) => {
    if (
      !tier.id ||
      tier.id.length > 512 ||
      tier.id !== tier.id.trim() ||
      seen.has(tier.id) ||
      tier.status.pickerVisible === false
    )
      return [];
    seen.add(tier.id);
    return [
      {
        id: tier.id,
        label: tier.displayName.trim() || tier.id,
        ...(tier.description.trim() ? { description: tier.description.trim() } : {}),
        ...(!tier.status.enabled
          ? {
              disabledReason:
                tier.status.message?.trim() ||
                tier.status.reason?.trim() ||
                "Unavailable for this account.",
            }
          : {}),
        ...(tier.id === auto.defaultTier && tier.status.enabled ? { isDefault: true } : {}),
      },
    ];
  });
  let resetId = "provider-default";
  while (seen.has(resetId)) resetId = `_${resetId}`;
  options.push({
    id: resetId,
    label: "Provider default",
    description: "Explicitly clear the saved routing preference.",
    isReset: true,
  });
  return {
    id: "autoTier",
    label: auto.tiers.some((tier) => tier.type === "fusion") ? "Fusion effort" : "Routing",
    type: "select",
    options,
    ...(options.some((option) => option.id === auto.defaultTier && !option.disabledReason)
      ? { currentValue: auto.defaultTier }
      : {}),
  };
}

export function autoTierForSelection(selection: ModelSelection, auto?: AutoCatalog) {
  const requested = getProviderOptionStatedValue("autoTier", selection);
  if (selection.model !== "auto") {
    if (requested !== undefined)
      throw new Error("A Copilot routing preference requires the account-advertised auto model.");
    return undefined;
  }
  if (requested === undefined) return undefined;
  if (requested === false) return null;
  if (typeof requested !== "string")
    throw new Error("A Copilot routing preference must be an advertised tier or provider default.");
  if (!auto)
    throw new Error("This Copilot runtime/account does not advertise routing preferences.");
  const id = requested;
  const tier = auto.tiers.find((entry) => entry.id === id);
  if (!tier || tier.id.length > 512 || !tier.status.enabled || tier.status.pickerVisible === false)
    throw new Error(
      tier?.status.message ||
        tier?.status.reason ||
        "The requested Copilot routing preference is unavailable for this account.",
    );
  return requested;
}

import { assert, describe, it } from "@effect/vitest";
import type { ModelInfo, SkillsLoadedSkill } from "@github/copilot-sdk";
