describe("descriptor helpers", () => {
  it("round trips an explicit reset without dispatching the picker-only choice ID", () => {
    const caps = createModelCapabilities({
      optionDescriptors: [
        {
          id: "autoTier",
          label: "Fusion effort",
          type: "select",
          currentValue: "balance",
          options: [
            { id: "balance", label: "Standard", isDefault: true },
            { id: "reset", label: "Provider default", isReset: true },
          ],
        },
      ],
    });
    const selection = createModelSelection(ProviderInstanceId.make("githubCopilot"), "auto", [
      { id: "autoTier", value: false },
    ]);
    const descriptors = getProviderOptionDescriptors({ caps, selections: selection.options });
    expect(getProviderOptionCurrentValue(descriptors[0])).toBe("reset");
    expect(getProviderOptionCurrentLabel(descriptors[0], selection)).toBe("Provider default");
    expect(
      buildExplicitProviderOptionSelectionsFromDescriptors(descriptors, selection.options),
    ).toEqual([{ id: "autoTier", value: false }]);
    expect(buildProviderOptionSelectionsFromDescriptors(descriptors)).toEqual([
      { id: "autoTier", value: false },
    ]);
    expect(getProviderOptionCurrentLabel(caps.optionDescriptors?.[0], selection)).toBe(
      "Provider default",
    );
    expect(
      buildExplicitProviderOptionSelectionsFromDescriptors(descriptors, undefined),
    ).toBeUndefined();
  });
  it("preserves an opaque saved routing request that the destination no longer advertises", () => {
    const descriptors = getProviderOptionDescriptors({
      caps: createModelCapabilities({
        optionDescriptors: [
          {
            id: "autoTier",
            label: "Routing",
            type: "select",
            currentValue: "standard",
            options: [{ id: "standard", label: "Standard", isDefault: true }],
          },
        ],
      }),
      selections: [{ id: "autoTier", value: "former-account:opaque" }],
    });
    expect(
      buildExplicitProviderOptionSelectionsFromDescriptors(descriptors, [
        { id: "autoTier", value: "former-account:opaque" },
      ]),
    ).toEqual([{ id: "autoTier", value: "former-account:opaque" }]);
  });
  it("skips unavailable choices for defaults and navigation but preserves explicit unavailable requests", () => {
    const descriptor = {
      id: "routing",
      label: "Routing",
      type: "select" as const,
      options: [
        { id: "premium", label: "Premium", isDefault: true, disabledReason: "Not supported" },
        { id: "standard", label: "Standard" },
        { id: "economy", label: "Economy" },
      ],
    };
    expect(getProviderOptionCurrentValue(descriptor)).toBeUndefined();
    expect(
      providerOptionChoicesInCycleOrder(descriptor, "standard", 1).map(({ id }) => id),
    ).toEqual(["economy"]);
    expect(
      providerOptionChoicesInCycleOrder(descriptor, "economy", -1).map(({ id }) => id),
    ).toEqual(["standard"]);
    const descriptors = getProviderOptionDescriptors({
      caps: createModelCapabilities({ optionDescriptors: [descriptor] }),
      selections: [{ id: "routing", value: "premium" }],
    });
    expect(getProviderOptionCurrentLabel(descriptors[0])).toBe("Premium");
    expect(
      buildExplicitProviderOptionSelectionsFromDescriptors(descriptors, [
        { id: "routing", value: "premium" },
      ]),
    ).toEqual([{ id: "routing", value: "premium" }]);
    expect(
      providerOptionChoicesInCycleOrder(
        {
          ...descriptor,
          options: descriptor.options.slice(0, 1),
        },
        "premium",
        1,
      ),
    ).toEqual([]);
  });

  it("builds dispatch options only from explicit selections", () => {
    const descriptors = getProviderOptionDescriptors({
      caps: codexCaps,
      selections: [{ id: "fastMode", value: true }],
    });

    expect(buildExplicitProviderOptionSelectionsFromDescriptors(descriptors, undefined)).toBe(
      undefined,
    );
    expect(
      buildExplicitProviderOptionSelectionsFromDescriptors(descriptors, [
        { id: "fastMode", value: true },
      ]),
    ).toEqual([{ id: "fastMode", value: true }]);
  });

  it("compares complete model selections independent of option ordering", () => {
    const left = createModelSelection(ProviderInstanceId.make("codex"), "gpt-5.4", [
      { id: "reasoningEffort", value: "high" },
      { id: "fastMode", value: true },
    ]);
    const reordered = createModelSelection(ProviderInstanceId.make("codex"), "gpt-5.4", [
      { id: "fastMode", value: true },
      { id: "reasoningEffort", value: "high" },
    ]);

    expect(modelSelectionsEqual(left, reordered)).toBe(true);
    expect(
      modelSelectionsEqual(left, {
        ...reordered,
        options: [
          { id: "fastMode", value: true },
          { id: "reasoningEffort", value: "medium" },
        ],
      }),
    ).toBe(false);
    expect(modelSelectionsEqual(left, { ...reordered, model: "gpt-5.5" })).toBe(false);
  });
});

